			overview_description:
				'{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"ウズベキスタンの旅行手配会社として、TourLinkは欧州の旅行会社と旅行者の期待や運営基準を理解しています。柔軟性、適応力、サービス品質は私たちの重要な価値です。"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"ホテルへの考え方"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"ホテルは快適さ、美しさ、雰囲気、魅力を基準に選定し、特にブティックホテルを重視しています。提携ホテルは定期的に確認し、大都市では中心部に近い場所や休息に適した静かなエリアを優先します。大都市での送迎は手配され、サービスに含まれます。"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"レストランへの考え方"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"各行程の地域性に合わせてレストランを選定します。伝統的なレストランを重視し、各地域の味を楽しめるようメニューを調整します。"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"交通サービス"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"プロドライバー付き車両を手配し、品質を定期的に確認します。専属ガイドは慎重に選び、継続的に評価しています。"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"定番旅行と長期旅行"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"定番ツアーではウズベキスタンの主要都市と見どころを巡ります。長期滞在の場合は、打ち合わせ後に追加ルートや個別提案をご案内できます。"}]}]}',
			pickup_description: null,
